# -*- coding: utf-8 -*-
"""国信改良版.py 的聚宽研究回测移植；不包含原券商账号、Cookie或推送地址。"""
from jqdata import *
import datetime as dt
from decimal import Decimal, ROUND_HALF_UP
import math
import builtins
import numpy as np
import pandas as pd
import talib

INDEX = '399101.XSHE'
SLOTS = 7
TG_SIZE = 18
TG_DAYS = 20
TG_OPEN = 0.015
TG_CLOSE = 0.02
RSI_LIMIT = 80
STOCK_STOP = .87
STOCK_PROFIT = 1.33
INDEX_STOP = .95


def _tg_original_initialize(context):
    set_option('avoid_future_data', True)
    set_option('use_real_price', True)
    set_benchmark(INDEX)
    set_order_cost(OrderCost(open_tax=0, close_tax=.001, open_commission=.0003,
                             close_commission=.0003, close_today_commission=0,
                             min_commission=5), type='stock')
    # 国信代码未指定滑点模型；显式设零，不虚构两平台共同的撮合滑点。
    set_slippage(FixedSlippage(0))
    log.set_level('order','error')
    g.day = None
    g.tg_allow_open = False
    g.can_add_cover = True
    g.target_list = []
    g.tg_members = []
    g.damaged = set()
    g.yesterday_limit = set()
    g.daily_prices = {}
    g.prev_prices = {}
    g.last_tg = None
    g.audit_counts = {'select':0,'tg_checked':0,'tg_skipped':0,'buy':0,'sell':0}


def _round2(v):
    return float(Decimal(str(v)).quantize(Decimal('0.01'),rounding=ROUND_HALF_UP))


def _day(context):
    return str(context.current_dt.date())


def _prev(context):
    return str(context.previous_date)


def _current(codes):
    return get_current_data(list(codes)) if codes else {}


def _uncached_raw_previous(codes, context, count=2):
    """按历史日期定位；拒绝把正在形成的今日K线当昨日收盘。"""
    codes=list(codes)
    if not codes:return {}
    d=get_price(codes, end_date=_prev(context), count=count, frequency='daily',
                fields=['close','money','paused'],skip_paused=False,fq='pre',panel=False)
    out={}
    if d is None or len(d)==0:return out
    for code,group in d.groupby('code'):
        values=[]
        for row in group.sort_values('time').itertuples():
            day=str(row.time)[:10]
            if day<=_prev(context):values.append({'day':day,'close':float(row.close),'money':float(row.money),'paused':bool(row.paused)})
        if values:out[code]=values
    return out


def _recent_price(code,context):
    p=g.prev_prices.get(code)
    if p is None:
        p=_raw_previous([code],context,count=2).get(code,[])
        g.prev_prices[code]=p
    return p


def _last_price(code,context):
    q=_current([code])[code]
    return float(q.last_price) if not q.paused and q.last_price>0 else None


def _is_limit(code,context):
    bars=_recent_price(code,context)
    p=_last_price(code,context)
    return bool(len(bars)>=1 and p is not None and _round2(p)>=_round2(bars[-1]['close']*1.10))


def _previous_limit(code,context):
    bars=_recent_price(code,context)
    if len(bars)<2:return False
    return _round2(bars[-1]['close'])>=_round2(bars[-2]['close']*1.10)


def _positions(context):
    return context.portfolio.positions


def _sell(context,code,reason):
    if code not in _positions(context):return
    q=_current([code])[code]
    if q.paused or q.last_price<=0:return
    o=order_target_value(code,0)
    g.damaged.add(code)
    if o is not None:
        g.audit_counts['sell']+=1
        log.info('PORT_SELL|%s|%s|%s|%s'%(str(context.current_dt),code,reason,getattr(o,'filled',0)))


def _uncached_five_bars(code,context):
    d=get_price(code,end_date=context.current_dt,count=50,frequency='5m',
                fields=['close','volume'],fq='pre',skip_paused=False)
    return d.sort_index() if d is not None else None


def _rsi_overbought(code,context):
    d=_five_bars(code,context)
    if d is None or len(d)<10:return False
    close=d['close'].values.astype(float)
    value=talib.RSI(close,timeperiod=6)
    return bool(np.isfinite(value[-1]) and value[-1]>=RSI_LIMIT)


def _buy(context,codes,source):
    if not g.tg_allow_open:return
    nav=float(context.portfolio.total_value)
    for code in codes:
        if len(_positions(context))>=SLOTS:break
        if code in _positions(context) or code in g.damaged:continue
        q=_current([code])[code]
        if q.paused or q.last_price<=0 or q.last_price>=q.high_limit:continue
        if _rsi_overbought(code,context):continue
        o=order_value(code,nav/SLOTS)
        if o is not None:
            g.audit_counts['buy']+=1
            log.info('PORT_BUY|%s|%s|%s|%s'%(str(context.current_dt),code,source,getattr(o,'filled',0)))
    _top_up(context)


def _top_up(context):
    held=list(_positions(context).items())
    if len(held)<SLOTS:return
    target=float(context.portfolio.total_value)/len(held)
    for code,pos in sorted(held,key=lambda kv:kv[1].total_amount*kv[1].avg_cost):
        if code not in g.target_list:continue
        cost=pos.total_amount*pos.avg_cost
        if cost>=.9*target:continue
        available=float(context.portfolio.available_cash)
        q=_current([code])[code]
        if q.paused or q.last_price<=0 or available<q.last_price*100:continue
        if _rsi_overbought(code,context):continue
        gap=target-cost
        if gap>=available:continue
        if gap<q.last_price*100:o=order(code,100)
        else:o=order_value(code,gap)
        if o is not None:log.info('PORT_ADD|%s|%s|%s'%(str(context.current_dt),code,getattr(o,'filled',0)))


def _select(context):
    """仅排序改为前一交易日总市值；TG取前18，买入观察取前14，其余资格条件保留。"""
    day=_day(context);pool=list(get_index_stocks(INDEX,date=day))
    info=get_all_securities(['stock'],date=day)
    start_dates=info['start_date'].to_dict()
    # 名称和ST必须使用回测当时的快照；get_all_securities的名称可能是后来的名称。
    current=get_current_data()
    small=[]
    for code in pool:
        if code not in info.index:continue
        if code.startswith(('4','8','9','30','68')):continue
        quote=current[code]
        name=str(quote.name)
        if quote.is_st or not name or '退' in name or '*' in name or 'ST' in name:continue
        if (context.current_dt.date()-start_dates[code]).days<=375:continue
        small.append(code)
    bars=_raw_previous(small,context,count=2)
    frame=_cached_valuation(small,context)
    ratios={str(r.code):float(r.turnover_ratio)/100 for r in frame.itertuples()} if frame is not None else {}
    total_caps={str(r.code):float(r.market_cap) for r in frame.itertuples()} if frame is not None else {}
    old=set(_positions(context))
    candidates=[]
    for code in small:
        rows=bars.get(code,[])
        if len(rows)<2:continue
        yesterday,before=rows[-1],rows[-2]
        close=yesterday['close'];money=yesterday['money'];turn=ratios.get(code)
        if not math.isfinite(close) or close<=0 or not math.isfinite(money) or money<=0 or turn is None or not math.isfinite(turn) or turn<=0:continue
        rounded=_round2(close)
        if code not in old and (rounded>=_round2(before['close']*1.10) or rounded<=_round2(before['close']*.90)):continue
        if not 1<=rounded<=99:continue
        cap=total_caps.get(code)
        # 不因缺少总市值静默改变候选资格；有缺数则中止，先核查数据。
        if cap is None or not math.isfinite(cap) or cap<=0:
            raise ValueError('Missing previous-day market_cap for eligible stock: '+code)
        candidates.append((cap,code))
    candidates.sort(key=lambda p:p[0])
    # 国信回测跳过外部公告搜索；最多考察前36并取前18。
    tops=[code for cap,code in candidates[:max(4*SLOTS,2*TG_SIZE)]][:max(2*SLOTS,TG_SIZE)]
    g.tg_members=tops[:TG_SIZE]
    g.target_list=tops[:2*SLOTS]
    g.audit_counts['select']+=1
    fields={'pool_n':len(pool),'small_n':len(small),'ranked_n':len(candidates)}
    fields.update({'pick_%d'%(i+1):int(c[:6]) for i,c in enumerate(g.target_list)})
    fields.update({'tg_code_%d'%(i+1):int(c[:6]) for i,c in enumerate(g.tg_members)})
    record(**fields)
    log.info('PORT_SELECT|%s|pool=%d|small=%d|ranked=%d|tg=%s|buy=%s'%(day,len(pool),len(small),len(candidates),','.join(g.tg_members),','.join(g.target_list)))
    return g.target_list


def _tg(context):
    if not g.tg_members:_select(context)
    codes=list(g.tg_members)
    if len(codes)<TG_SIZE:g.audit_counts['tg_skipped']+=1;log.info('TG_SKIP|%s|FEW_MEMBERS|%d'%(_day(context),len(codes)));return
    h=_cached_tg_history(codes,context)
    if h is None or h.empty:g.audit_counts['tg_skipped']+=1;log.info('TG_SKIP|%s|DAILY_EMPTY'%(_day(context)));return
    pivot=h.pivot(index='time',columns='code',values='close').sort_index()
    if builtins.any(c not in pivot.columns for c in codes):g.audit_counts['tg_skipped']+=1;log.info('TG_SKIP|%s|DAILY_MISSING|%s|rows=%d'%(_day(context),str(sorted(set(codes)-set(pivot.columns))),len(h)));return
    q=_current(codes);now={}
    for c in codes:
        try:z=q[c]
        except (KeyError,ValueError):g.audit_counts['tg_skipped']+=1;log.info('TG_SKIP|%s|QUOTE_KEY|%s'%(_day(context),c));return
        if z.paused or not np.isfinite(z.last_price) or z.last_price<=0:
            g.audit_counts['tg_skipped']+=1;log.info('TG_SKIP|%s|QUOTE_BAD|%s|%s|%s'%(_day(context),c,z.paused,z.last_price));return
        now[c]=float(q[c].last_price)
    pivot.loc[pd.Timestamp(context.current_dt.date())]=pd.Series(now)
    rets=pivot.pct_change().mean(axis=1,skipna=True)
    index=pd.Series(1000.,index=rets.index,dtype=float)
    if len(index)>1:index.iloc[1:]=1000.*(1+rets.iloc[1:].fillna(0)).cumprod()
    if len(index)<=TG_DAYS:g.audit_counts['tg_skipped']+=1;log.info('TG_SKIP|%s|HISTORY_SHORT|%d'%(_day(context),len(index)));return
    latest=float(index.iloc[-1]);ma=float(index.iloc[-(TG_DAYS+1):-1].mean())
    if not np.isfinite(latest) or not np.isfinite(ma) or ma<=0:g.audit_counts['tg_skipped']+=1;log.info('TG_SKIP|%s|VALUE_BAD'%(_day(context)));return
    old=g.tg_allow_open;dev=latest/ma-1
    g.last_tg=(latest,ma,dev)
    g.audit_counts['tg_checked']+=1
    _apply_tg_with_exemption(context,dev)
    log.info('PORT_TG|%s|%.6f|%.6f|%.6f|%s|%s'%(str(context.current_dt),latest,ma,dev,'OPEN' if g.tg_allow_open else 'CLOSED',','.join(codes)))
    tag='tg0940' if context.current_dt.hour==9 else 'tg1440'
    record(**{tag:latest,tag+'_ma20':ma,tag+'_dev':dev,tag+'_open':int(g.tg_allow_open)})


def _uncached_new_day(context):
    g.day=_day(context);g.target_list=[];g.tg_members=[];g.damaged=set();g.can_add_cover=True;g.prev_prices={}
    held=set(_positions(context))
    g.yesterday_limit={c for c in held if _previous_limit(c,context)}
    current_limit={c for c in held if _is_limit(c,context)}
    g.tg_allow_open=bool(held-g.yesterday_limit-current_limit)
    if not g.tg_allow_open:g.can_add_cover=False
    log.info('PORT_DAY|%s|held=%s|previous_limit=%s|tg=%s'%(g.day,','.join(sorted(held)),','.join(sorted(g.yesterday_limit)),int(g.tg_allow_open)))


def _broken_low(context):
    for c in list(g.yesterday_limit):
        if c not in _positions(context):continue
        p=_last_price(c,context);bars=_recent_price(c,context)
        if p is None or not bars:continue
        if (p/bars[-1]['close']-1)*100<-3:_sell(context,c,'BROKEN_LOW')


def _broken(context):
    for c in list(g.yesterday_limit):
        if c in _positions(context) and not _is_limit(c,context):_sell(context,c,'BROKEN')


def _risk(context):
    if not _positions(context):return
    p=_last_price(INDEX,context);bars=_recent_price(INDEX,context)
    if p is None or not bars:return
    if p/bars[-1]['close']<=INDEX_STOP:
        for c in list(_positions(context)):_sell(context,c,'INDEX_STOP')
        g.can_add_cover=False;return
    for c,pos in list(_positions(context).items()):
        quote=_last_price(c,context)
        if quote is None:continue
        if quote<pos.avg_cost*STOCK_STOP:
            _sell(context,c,'STOCK_STOP');g.can_add_cover=False
        if c in _positions(context) and quote>=pos.avg_cost*STOCK_PROFIT and not _is_limit(c,context):_sell(context,c,'STOCK_PROFIT')


def _rebalance(context):
    _select(context)
    target=[c for c in g.target_list if c not in g.damaged][:SLOTS]
    if not g.tg_allow_open:return
    for c in list(_positions(context)):
        if c not in target and c not in g.yesterday_limit:_sell(context,c,'WEEKLY')
    _buy(context,target,'WEEKLY')


def _cover(context):
    if not g.can_add_cover or not g.tg_allow_open:return
    _buy(context,[c for c in g.target_list if c not in _positions(context) and c not in g.damaged][:SLOTS-len(_positions(context))],'COVER')


def _mark(context):
    record(held=len(_positions(context)),cash=float(context.portfolio.available_cash),
           equity=float(context.portfolio.total_value),tg_open=int(g.tg_allow_open),
           selections=g.audit_counts['select'],tg_checked=g.audit_counts['tg_checked'],
           buys=g.audit_counts['buy'],sells=g.audit_counts['sell'])


def _tg_original_handle_data(context,data):
    day=_day(context)
    now=context.current_dt
    h,m=now.hour,now.minute
    if day!=g.day:
        if h==9 and m<31:return
        _new_day(context)
    if (h,m)==(9,40):_tg(context)
    elif (h,m) in ((9,50),(13,20)):_broken(context)
    elif (h,m)==(10,0):_risk(context)
    elif (h,m)==(10,30) and now.weekday()==1:_rebalance(context)
    elif (h,m) in ((10,45),(14,45)):_cover(context)
    elif (h,m)==(14,40):_tg(context)
    if h==9 and 31<=m<50:_broken_low(context)
    if (m%5==0 and (h,m)!=(9,30)) and h in (9,10,11,13,14):
        # 国信代码在回测模式跳过个股异动检测。
        pass
    if (h,m)==(14,57):_mark(context)

