TG_EXEMPT_TRADING_DAYS=10

def initialize(context):
    _before_exempt_initialize(context)
    g.exempt_remaining=0
    g.exempt_last_day=None
    g.exempt_entry_day=None
    g.exempt_expiry_pending=False
    g.normal_tg_allow=False
    g.exempt_started_n=0
    g.exempt_expired_n=0
    g.exempt_suppressed_n=0

def _new_day(context):
    was_active=g.exempt_remaining>0
    _before_exempt_new_day(context)
    day=_day(context)
    if was_active:
        if g.exempt_last_day!=day:
            g.exempt_remaining-=1
            g.exempt_last_day=day
        if g.exempt_remaining>0:
            g.tg_allow_open=True
            g.can_add_cover=True
        else:
            g.exempt_expiry_pending=True
            g.tg_allow_open=False
            g.can_add_cover=False
            log.info('EXEMPT_DUE|%s|entry=%s|normal=%d' % (day,g.exempt_entry_day,int(g.normal_tg_allow)))
    elif not g.exempt_expiry_pending:
        # Preserve original daily initialization outside an exemption.
        g.normal_tg_allow=bool(g.tg_allow_open)

def _tg_close_positions(context,reason):
    keep={c for c in _positions(context) if _is_limit(c,context)}
    for c in list(_positions(context)):
        if c not in keep:_sell(context,c,reason)
    g.tg_allow_open=False
    g.can_add_cover=False

def _normal_tg_actions(context,dev):
    if dev<-TG_CLOSE:
        _tg_close_positions(context,'TG_CLOSE')
    elif dev>TG_OPEN:
        if not g.tg_allow_open:
            g.tg_allow_open=True
            g.can_add_cover=True
            _buy(context,[c for c in g.target_list if c not in g.damaged][:SLOTS],'TG_OPEN')

def _finish_exemption(context):
    g.exempt_expiry_pending=False
    g.exempt_expired_n+=1
    if g.normal_tg_allow:
        g.tg_allow_open=True
        g.can_add_cover=True
        action='NORMAL_HOLD'
    else:
        _tg_close_positions(context,'EXEMPT_EXPIRE')
        action='NORMAL_CLOSE'
    log.info('EXEMPT_END|%s|entry=%s|normal=%d|action=%s' %
             (str(context.current_dt),g.exempt_entry_day,int(g.normal_tg_allow),action))
    g.exempt_entry_day=None

def _apply_tg_with_exemption(context,dev):
    # The background signal has its own state. Forced holdings never reopen it.
    if dev<-TG_CLOSE:g.normal_tg_allow=False
    elif dev>TG_OPEN:g.normal_tg_allow=True
    if g.exempt_remaining>0:
        g.tg_allow_open=True
        # Do not undo an independent risk check that has already stopped cover.
        if dev<-TG_CLOSE:g.exempt_suppressed_n+=1
        log.info('EXEMPT_TG|%s|left=%d|normal=%d|dev=%.12f' %
                 (str(context.current_dt),g.exempt_remaining,int(g.normal_tg_allow),dev))
        return
    if g.exempt_expiry_pending:
        _finish_exemption(context)
        return
    _normal_tg_actions(context,dev)
    g.normal_tg_allow=bool(g.tg_allow_open)

def _base_force_enter(context):
    before=g.base_force_attempt_n
    normal_before=bool(g.tg_allow_open)
    _before_exempt_force_enter(context)
    if g.base_force_attempt_n>before:
        g.exempt_remaining=TG_EXEMPT_TRADING_DAYS
        g.exempt_last_day=_day(context)
        g.exempt_entry_day=_day(context)
        g.exempt_expiry_pending=False
        g.normal_tg_allow=normal_before
        g.exempt_started_n+=1
        log.info('EXEMPT_START|%s|days=%d|normal=%d' %
                 (str(context.current_dt),TG_EXEMPT_TRADING_DAYS,int(g.normal_tg_allow)))

def _event_dispatch(context):
    _before_exempt_event_dispatch(context)
    # If a TG check has missing quotes on day 11, use its latest valid normal
    # permission, never the permission inherited from forced holdings.
    if g.exempt_expiry_pending and (context.current_dt.hour,context.current_dt.minute)==(9,40):
        _finish_exemption(context)

def after_trading_end(context):
    if g.exempt_remaining>0 and not _positions(context):
        # Independent exits or entirely unfilled attempts end this holding task.
        log.info('EXEMPT_EMPTY_END|%s|entry=%s|left=%d' %
                 (_day(context),g.exempt_entry_day,g.exempt_remaining))
        g.exempt_remaining=0
        g.exempt_entry_day=None
        g.exempt_expiry_pending=False
        g.tg_allow_open=bool(g.normal_tg_allow)
        if not g.tg_allow_open:g.can_add_cover=False
    _before_exempt_after_trading_end(context)
    record(exempt_left=g.exempt_remaining,normal_tg_open=int(g.normal_tg_allow),
           exempt_started=g.exempt_started_n,exempt_expired=g.exempt_expired_n,
           exempt_suppressed=g.exempt_suppressed_n)
